<?php
ini_set('memory_limit','768M');require __DIR__.'/lib.php';require __DIR__.'/size-insights-lib.php';admin_init();if(!admin_logged_in()){header('Location: /quan-tri/');exit;}people_require_owner();$user=team_identity();$saveError='';if($_SERVER['REQUEST_METHOD']==='POST'){try{admin_csrf();size_version_save(admin_db(),$_POST,$user);header('Location: size-insights.php?saved=1');exit;}catch(Throwable $e){$saveError=$e->getMessage();}}try{$data=size_insights(admin_db(),$_GET);}catch(Throwable $e){http_response_code(400);exit(h($e->getMessage()));}if(isset($_GET['format'])){header('Content-Type: application/json');echo json_encode(['alerts'=>$data['alerts']],JSON_UNESCAPED_UNICODE);exit;}$sku=(string)($_GET['sku']??'');?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KHUYẾN NGHỊ SIZE · THE VICTOR</title><link rel="stylesheet" href="admin.css?v=52"><link rel="stylesheet" href="mkt.css?v=53"><link rel="stylesheet" href="size-insights.css?v=57"></head><body><?php require __DIR__.'/admin-header.php';?><main class="dashboard"><div class="page-heading"><div><h1>KHUYẾN NGHỊ BẢNG SIZE</h1><p><?=$data['alerts']?> mã có đợt / tổng tỷ lệ hoàn trên 35% · BẢNG ĐƠN phiên bản <?=$data['version']?></p></div><a href="?from=&amp;to=" class="secondary">Tất cả thời gian</a></div><?php if($saveError):?><p class="error" role="alert"><?=h($saveError)?></p><?php elseif(isset($_GET['saved'])):?><p class="notice">Đã lưu lịch sử áp dụng bảng size.</p><?php endif;?><form class="filters"><label>Từ ngày<input type="date" name="from" value="<?=h($_GET['from']??'')?>"></label><label>Đến ngày<input type="date" name="to" value="<?=h($_GET['to']??'')?>"></label><label>Mã sản phẩm<select name="sku"><option value="">Tất cả mã</option><?php foreach($data['products'] as $p):?><option <?=$sku===$p['sku']?'selected':''?>><?=h($p['sku'])?></option><?php endforeach;?></select></label><button class="primary">Xem phân tích</button></form><section class="mkt-card"><h2>So sánh các đợt áp dụng bảng size</h2><p>Gắn theo ngày của sheet khi tạo đơn. Đơn hoàn muộn vẫn thuộc đợt gốc; chưa rõ kết quả không coi là nhận thành công. Mỗi mã chỉ có một bảng size trong cùng một ngày.</p><div class="mkt-table-wrap"><table><thead><tr><th>Mã</th><th>Phiên bản</th><th>Ngày áp dụng</th><th>Đơn gửi</th><th>Đơn có hoàn</th><th>Tỷ lệ hoàn</th><th>Tỷ lệ chiếc đã nhận</th><th>Chiếc chưa có kết quả</th><th>Chưa rõ hàng hoàn</th></tr></thead><tbody><?php foreach($data['versionStats'] as $v):if($sku!==''&&$sku!==$v['sku'])continue;?><tr <?=$v['alert']?'class="negative"':''?>><th><?=h($v['sku'])?></th><td><?=h($v['version']['name'])?></td><td><?php if($v['version']['id']):?><?=h($v['version']['date_from'])?> → <?=h($v['version']['date_to']?:'Đang áp dụng')?><?php else:?>—<?php endif;?></td><td><?=$v['sentOrders']?></td><td><?=$v['returnOrders']?></td><td><b><?=$v['returnRate']?>%</b></td><td><?=$v['acceptedRate']?>%</td><td><?=$v['pendingQty']?></td><td><?=$v['unresolved']?></td></tr><?php endforeach;?></tbody></table></div></section>
<details class="mkt-card"><summary>Quản lý lịch sử bảng size theo sản phẩm</summary><form method="post" class="size-version-form"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><label>Mã sản phẩm<input name="sku" maxlength="40" required value="<?=h($sku)?>" placeholder="E1"></label><label>Tên phiên bản<input name="name" maxlength="100" required placeholder="Bảng size số 1"></label><label>Từ ngày<input name="date_from" type="date" required></label><label>Đến ngày<input name="date_to" type="date"><small>Để trống nếu đang áp dụng. Kết thúc bản cũ trước khi thêm bản mới.</small></label><label class="wide">Nội dung bảng size<textarea name="chart" rows="5" maxlength="10000" required placeholder="Ghi size và khoảng chiều cao / cân nặng thực tế đang áp dụng"></textarea></label><label class="wide">Ghi chú<textarea name="note" rows="2" maxlength="1000"></textarea></label><button class="primary">Lưu phiên bản bảng size</button></form><p>Nội dung từng phiên bản được giữ nguyên để đối chiếu. Khi đổi cách tư vấn, tạo phiên bản mới. Điều chỉnh ngày kết thúc được lưu nhật ký; hệ thống đối soát lại bằng ngày gốc đã ghi nhận của đơn.</p><?php foreach($data['versions'] as $v):if($sku!==''&&$sku!==$v['sku'])continue;?><details><summary><?=h($v['sku'].' · #'.$v['id'].' '.$v['name'].' · '.$v['date_from'].' → '.($v['date_to']?:'Đang áp dụng'))?></summary><pre><?=h($v['chart'])?></pre><p><?=h($v['note'])?></p><form method="post" class="stock-form-options"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="close_id" value="<?=$v['id']?>"><input type="hidden" name="revision" value="<?=$v['revision']?>"><label>Ngày kết thúc<input type="date" name="date_to" value="<?=h($v['date_to'])?>" required min="<?=h($v['date_from'])?>"></label><button class="secondary">Lưu ngày kết thúc</button></form></details><?php endforeach;?></details>
<section class="mkt-card"><h2>Tỷ lệ theo sản phẩm</h2><p>Tỷ lệ hoàn = số đơn có sản phẩm hoàn / số đơn đã gửi của mã đó. Tỷ lệ nhận tính theo số chiếc có bằng chứng đã nhận; đơn chưa có kết quả không được coi là nhận thành công.</p><div class="mkt-table-wrap"><table><thead><tr><th>Mã</th><th>Đơn gửi</th><th>Đơn có hoàn</th><th>Tỷ lệ hoàn</th><th>Tỷ lệ chiếc đã nhận</th><th>Có cao / nặng</th><th>Hoàn do size</th><th>Chưa rõ hàng hoàn</th></tr></thead><tbody><?php foreach($data['products'] as $p):if($sku!==''&&$sku!==$p['sku'])continue;?><tr <?=$p['alert']?'class="negative"':''?>><th><?=h($p['sku'])?><?=$p['alert']?' ⚠':''?></th><td><?=$p['sentOrders']?></td><td><?=$p['returnOrders']?></td><td><b><?=$p['returnRate']?>%</b></td><td><?=$p['acceptedRate']?>%</td><td><?=$p['measured']?> chiếc</td><td><?=$p['fitReturns']?> chiếc</td><td><?=$p['pendingQty']?></td><td><?=$p['unresolved']?> đơn</td></tr><?php endforeach;?></tbody></table></div></section><section class="mkt-card"><h2>Đề nghị điều chỉnh bảng size</h2><p>So sánh khách có chiều cao trong cùng nhóm 5 cm và cân nặng trong cùng nhóm 5 kg. Chỉ đề nghị khi mỗi size có ít nhất 20 mẫu có kết quả, tỷ lệ mẫu đủ kết quả từ 80%, size đề xuất có ít nhất 10 mẫu nhận thành công, chênh lệch hoàn từ 10 điểm % và khoảng tin cậy 95% tách biệt. Các lý do như bom hàng không được coi là lỗi size.</p><div class="mkt-table-wrap"><table><thead><tr><th>Mã</th><th>Chiều cao</th><th>Cân nặng</th><th>Size hiện tại</th><th>Đề nghị thử</th><th>Hoàn do size trước / sau</th><th>Mẫu trước / sau</th></tr></thead><tbody><?php $found=false;foreach($data['proposals'] as $p):if($sku!==''&&$sku!==$p['sku'])continue;$found=true;?><tr><th><?=h($p['sku'])?></th><td><?=h($p['height'])?></td><td><?=h($p['weight'])?></td><td><?=h($p['from'])?></td><td><b><?=h($p['to'])?></b></td><td><?=$p['before']?>% / <?=$p['after']?>%</td><td><?=h($p['samples'])?></td></tr><?php endforeach;if(!$found):?><tr><td colspan="7">Chưa đủ bằng chứng để đề nghị đổi size. Tiếp tục điền cao / nặng và đối soát kết quả nhận / hoàn.</td></tr><?php endif;?></tbody></table></div><p>Đây là đề nghị thử nghiệm từ dữ liệu đã ghi nhận, không bảo đảm tỷ lệ hoàn tương lai. Bảng size trên website chỉ thay đổi sau khi quản trị viên quyết định.</p></section><details class="mkt-card"><summary>Xem dữ liệu chiều cao / cân nặng theo từng size</summary><div class="mkt-table-wrap"><table><thead><tr><th>Mã</th><th>Chiều cao</th><th>Cân nặng</th><th>Size / phiên bản</th><th>Mẫu nhận</th><th>Mẫu hoàn do size</th></tr></thead><tbody><?php foreach($data['cohorts'] as $b):if($sku!==''&&$sku!==$b['sku'])continue;foreach($b['sizes'] as $size=>$counts):?><tr><th><?=h($b['sku'])?></th><td><?=$b['height']?>–<?=$b['height']+4?> cm</td><td><?=$b['weight']?>–&lt;<?=$b['weight']+5?> kg</td><td><?=h($size)?></td><td><?=$counts['accepted']?></td><td><?=$counts['returned']?></td></tr><?php endforeach;endforeach;?></tbody></table></div></details></main><script type="module" src="date-picker.js?v=22"></script></body></html>
